// 原生懒加载实现
const LazyImage = ({ src, alt, placeholder, className }) => {
  const [isLoaded, setIsLoaded] = useState(false);
  const [isInView, setIsInView] = useState(false);
  const imgRef = useRef();

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsInView(true);
          observer.disconnect();
        }
      },
      { threshold: 0.1 }
    );

    if (imgRef.current) {
      observer.observe(imgRef.current);
    }

    return () => observer.disconnect();
  }, []);

  return (
    <div ref={imgRef} className={className}>
      {isInView ? (
        <img
          src={src}
          alt={alt}
          loading="lazy"
          onLoad={() => setIsLoaded(true)}
          style={{
            opacity: isLoaded ? 1 : 0,
            transition: 'opacity 0.3s ease'
          }}
        />
      ) : (
        <div className="image-placeholder">
          {placeholder || <div className="skeleton-loader" />}
        </div>
      )}
    </div>
  );
};

// 高级懒加载 - 渐进式加载
const ProgressiveImage = ({ src, placeholderSrc, alt }) => {
  const [imgSrc, setImgSrc] = useState(placeholderSrc || '');
  const [isLoaded, setIsLoaded] = useState(false);

  useEffect(() => {
    const img = new Image();
    img.src = src;
    img.onload = () => {
      setImgSrc(src);
      setIsLoaded(true);
    };
  }, [src]);

  return (
    <img
      src={imgSrc}
      alt={alt}
      style={{
        filter: isLoaded ? 'none' : 'blur(5px)',
        transition: 'filter 0.3s ease'
      }}
    />
  );
};

// 响应式图片组件
const ResponsiveImage = ({ 
  src, 
  alt, 
  sizes, 
  breakpoints = [320, 768, 1024, 1920],
  className 
}) => {
  const generateSrcSet = (baseSrc, breakpoints) => {
    return breakpoints.map(width => 
      \`\${baseSrc}?w=\${width}&q=80 \${width}w\`
    ).join(', ');
  };

  return (
    <picture>
      {/* WebP格式支持 */}
      <source
        type="image/webp"
        srcSet={generateSrcSet(src, breakpoints)}
        sizes={sizes}
      />
      {/* 传统格式fallback */}
      <img
        src={src}
        alt={alt}
        srcSet={generateSrcSet(src, breakpoints)}
        sizes={sizes}
        loading="lazy"
        className={className}
      />
    </picture>
  );
};

