// 字体预加载
class FontOptimizer {
  static preloadFont(fontUrl, fontFamily) {
    const link = document.createElement('link');
    link.rel = 'preload';
    link.as = 'font';
    link.type = 'font/woff2';
    link.crossOrigin = 'anonymous';
    link.href = fontUrl;
    document.head.appendChild(link);

    // 创建字体face
    const fontFace = new FontFace(
      fontFamily,
      `url(${fontUrl})`,
      { display: 'swap' }
    );

    document.fonts.add(fontFace);
    fontFace.load();
  }

  static createFontDisplayCSS() {
    return `
      @font-face {
        font-family: 'Inter';
        src: url('/fonts/inter-var.woff2') format('woff2');
        font-display: swap;
        font-weight: 100 900;
        font-style: normal;
      }
    `;
  }

  static optimizeFontLoading() {
    // 禁用FOUC (Flash of Unstyled Content)
    const style = document.createElement('style');
    style.textContent = `
      body {
        font-family: system-ui, -apple-system, sans-serif;
        visibility: visible;
      }

      .font-loaded {
        font-family: 'Inter', system-ui, sans-serif;
      }
    `;
    document.head.appendChild(style);

    // 字体加载完成后添加class
    document.fonts.ready.then(() => {
      document.body.classList.add('font-loaded');
    });
  }
}

// React字体组件
const OptimizedFont = ({ 
  children, 
  fontFamily = 'Inter', 
  className = '',
  fallback = 'system-ui' 
}) => {
  const [isFontLoaded, setIsFontLoaded] = useState(false);

  useEffect(() => {
    document.fonts.load('16px Inter').then(() => {
      setIsFontLoaded(true);
    });
  }, []);

  const fontClass = isFontLoaded ? 'font-loaded' : '';
  const combinedClassName = \`\${className} \${fontClass}\`.trim();

  return (
    <div 
      className={combinedClassName}
      style={{
        fontFamily: isFontLoaded ? `'Inter', ${fallback}` : fallback
      }}
    >
      {children}
    </div>
  );
};

